{"name": "plan_add", "arguments": {"tool": "line.setCode", "args": {"file": "features/book/pages/BookPage.tsx", "code": "// @line-base pages/DetailPage
// @line-route /books/:id
import Link from 'next/link';
import { DetailPage } from '../../../library/pages/DetailPage';
import books from '../../../library/fixtures/books.json';

interface Book { id: string; title: string; author: string; genre: string; year: number; pages: number; summary: string; available: boolean; }

export function BookPage({ params }: { params: { id: string } }) {
 const { id } = params;
 const item = (books as Book[]).find((entry) => entry.id === id);
 const back = <Link href="/">Back to Books</Link>;
 if (!item) {
 return <DetailPage title="Book not found" back={back} />;
 }
 return (
 <DetailPage title={item.title} back={back}>
 <p>{item.author}</p>
 <p>{item.genre}</p>
 <p>{String(item.year)}</p>
 <p>{String(item.pages)}</p>
 <p>{item.summary}</p>
 <p>{String(item.available)}</p>
 {/* BK-1: The page at `/books/<id>` has the book's title as its main heading and shows "by <author>", its g... — add it here */}
 </DetailPage>
 );
}
